args.content:
import {chromium} from 'playwright';
import {mkdirSync} from 'node:fs';

const URL = 'http://127.0.0.1:5181/';
const OUT = '/tmp/shots';
mkdirSync(OUT, {recursive: true});

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1280, height: 800}});
const errors = [];
page.on('console', (m) => {
  if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`);
});
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

await page.goto(URL, {waitUntil: 'load'});
await page.waitForSelector('.cpu-chart__plot .uplot canvas', {timeout: 15000});
await page.waitForTimeout(800);

const geometry = () =>
  page.evaluate(() => {
    const host = document.querySelector('.cpu-chart__plot').getBoundingClientRect();
    const wrap = document.querySelector('.cpu-chart').getBoundingClientRect();
    const canvas = document.querySelector('.cpu-chart__plot .uplot canvas');
    const panel = document.querySelector('.monitor__panel').getBoundingClientRect();
    return {
      host: [Math.round(host.width), Math.round(host.height)],
      wrap: [Math.round(wrap.width), Math.round(wrap.height)],
      panel: [Math.round(panel.width), Math.round(panel.height)],
      canvasCss: canvas ? [Math.round(canvas.getBoundingClientRect().width), Math.round(canvas.getBoundingClientRect().height)] : null,
      pageScrollH: document.documentElement.scrollHeight,
      innerH: window.innerHeight,
    };
  });

const consistency = () =>
  page.evaluate(() => {
    const {chart, feed} = window.__cpuDebug;
    const s = chart.config.series[0];
    return {
      feedLen: feed.values.length,
      cfgTimeline: chart.config.timeline.length,
      cfgData: s.data.length,
      uplotX: chart.uplot.data[0].length,
      lastT: [feed.timeline.at(-1), chart.config.timeline.at(-1)],
      lastV: [feed.values.at(-1), s.data.at(-1)],
      firstT: [feed.timeline[0], chart.config.timeline[0]],
      sameDataCount: feed.values.length === s.data.length,
      lineColor: s.lineColor,
    };
  });

const counts = () =>
  page.evaluate(() => ({
    uplots: document.querySelectorAll('.uplot').length,
    tooltips: document.querySelectorAll('.yagr-tooltip').length,
    canvases: document.querySelectorAll('canvas').length,
  }));

console.log('geometry initial', JSON.stringify(await geometry()));
console.log('consistency initial', JSON.stringify(await consistency()));
await page.screenshot({path: `${OUT}/1-light.png`});

// Let real-time ticks happen (2 s each).
await page.waitForTimeout(6500);
console.log('consistency after ~6.5s', JSON.stringify(await consistency()));
console.log('counts', JSON.stringify(await counts()));

// Hover to check tooltip.
const box = await page.locator('.cpu-chart__plot .uplot .u-over').boundingBox();
await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5);
await page.waitForTimeout(400);
const tip = await page.evaluate(() => {
  const el = document.querySelector('.yagr-tooltip');
  return el ? {display: getComputedStyle(el).display, text: el.innerText.slice(0, 200)} : null;
});
console.log('tooltip', JSON.stringify(tip));
await page.screenshot({path: `${OUT}/2-light-hover.png`});

// Switch to dark theme.
await page.getByText('Тёмная', {exact: true}).click();
await page.waitForTimeout(800);
console.log('after dark: consistency', JSON.stringify(await consistency()));
console.log('after dark: counts', JSON.stringify(await counts()));
console.log('bg', await page.evaluate(() => getComputedStyle(document.querySelector('.monitor')).backgroundColor));
await page.mouse.move(box.x + box.width * 0.3, box.y + box.height * 0.5);
await page.waitForTimeout(300);
await page.screenshot({path: `${OUT}/3-dark-hover.png`});

// Toggle several times to check for leaked instances.
for (let i = 0; i < 6; i++) {
  await page.getByText('Светлая', {exact: true}).click();
  await page.waitForTimeout(150);
  await page.getByText('Тёмная', {exact: true}).click();
  await page.waitForTimeout(150);
}
await page.waitForTimeout(500);
console.log('after 6 toggles: counts', JSON.stringify(await counts()));

// Resize the viewport to check the chart stretches with its container.
await page.setViewportSize({width: 900, height: 600});
await page.waitForTimeout(500);
console.log('geometry small', JSON.stringify(await geometry()));
await page.screenshot({path: `${OUT}/4-small.png`});
await page.setViewportSize({width: 1600, height: 1000});
await page.waitForTimeout(500);
console.log('geometry big', JSON.stringify(await geometry()));
await page.screenshot({path: `${OUT}/5-big.png`});

console.log('errors:', errors.length ? errors : 'none');
await browser.close();

