args.content:
// Runs the real Yagr core + the real simulated feed in jsdom (canvas stubbed).
// Verifies: incremental updates keep Yagr's data identical to the feed, sliding
// window stays fixed-size, dispose leaves no DOM/listeners behind, recreate is clean.
import {JSDOM} from '/tmp/pwcheck/node_modules/jsdom/lib/api.js';

const dom = new JSDOM('<!doctype html><body></body>', {pretendToBeVisual: true});
const {window} = dom;
for (const key of ['window', 'document', 'HTMLElement', 'Element', 'Node', 'navigator', 'requestAnimationFrame', 'cancelAnimationFrame', 'getComputedStyle', 'MouseEvent', 'Event', 'CustomEvent']) {
  if (!(key in globalThis)) globalThis[key] = window[key];
}
globalThis.window = window;
globalThis.document = window.document;
globalThis.devicePixelRatio = 1;
globalThis.ResizeObserver = class {
  observe() {}
  unobserve() {}
  disconnect() {}
};

// Canvas 2D stub: uPlot calls many drawing methods; we only need them to exist.
const ctx = new Proxy({measureText: () => ({width: 10})}, {
  get(target, key) {
    if (key in target) return target[key];
    return () => ({width: 10});
  },
  set(target, key, value) {
    target[key] = value;
    return true;
  },
});
window.HTMLCanvasElement.prototype.getContext = () => ctx;

const {default: Yagr} = await import('/home/sandbox/workspace/node_modules/@gravity-ui/yagr/dist/yagr.mjs');
const {createSimulatedCpuFeed} = await import('/home/sandbox/workspace/src/monitoring/cpuFeed.ts');

const SERIES_ID = 'cpu';
// Copy of createConfig() from src/monitoring/CpuUsageChart.tsx, plus a fixed size
// because jsdom has no layout.
function createConfig(feed, theme) {
  const line = theme === 'dark' ? '#3987e5' : '#2a78d6';
  return {
    timeline: feed.timeline.slice(),
    series: [{id: SERIES_ID, name: 'Загрузка CPU', type: 'area', data: feed.values.slice(), color: 'rgba(0,0,0,0.14)', lineColor: line, lineWidth: 2}],
    chart: {appearance: {theme, locale: 'ru'}, size: {adaptive: true, width: 900, height: 420}},
    legend: {show: false},
    scales: {y: {min: 0, max: 100}},
    axes: {y: {precision: 0, values: (_u, ticks) => ticks.map((t) => `${t}%`)}},
    tooltip: {strategy: 'none', onUpdate: 'none', value: (v) => (v == null ? '—' : `${Number(v).toFixed(1)}%`)},
  };
}

const sameArray = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);
const report = (label, obj) => console.log(label, JSON.stringify(obj));

// --- 1. Real feed + real incremental updates ---
const feed = createSimulatedCpuFeed({windowMs: 24 * 3600e3, stepMs: 2000});
report('feed points', {len: feed.values.length});

const host = document.createElement('div');
document.body.appendChild(host);
const chart = new Yagr(host, createConfig(feed, 'light'));
let updateMs = [];
const unsubscribe = feed.subscribe((t, v) => {
  const t0 = performance.now();
  chart.setSeries([t], [{id: SERIES_ID, data: [v]}], {incremental: true, splice: true});
  updateMs.push(performance.now() - t0);
});
feed.start();

await new Promise((r) => setTimeout(r, 6500));
feed.stop();

const s = chart.config.series[0];
report('after ticks', {
  feedLen: feed.values.length,
  cfgTimeline: chart.config.timeline.length,
  cfgData: s.data.length,
  uplotX: chart.uplot.data[0].length,
  uplotY: chart.uplot.data[1].length,
  timelineMatches: sameArray(chart.config.timeline, feed.timeline),
  dataMatches: sameArray(s.data, feed.values),
  uplotYMatches: sameArray(chart.uplot.data[1], feed.values),
  uplotXMatches: sameArray(chart.uplot.data[0], feed.timeline),
});
const avg = updateMs.reduce((a, b) => a + b, 0) / updateMs.length;
report('update ms', {count: updateMs.length, avg: +avg.toFixed(2), max: +Math.max(...updateMs).toFixed(2)});

// --- 2. Dispose like the component's cleanup ---
const nodesBefore = document.body.querySelectorAll('*').length;
unsubscribe();
chart.dispose();
report('after dispose', {
  uplotNodes: document.querySelectorAll('.uplot').length,
  tooltipNodes: document.querySelectorAll('.yagr-tooltip').length,
  hostChildren: host.childNodes.length,
  bodyNodesBefore: nodesBefore,
  bodyNodesAfter: document.body.querySelectorAll('*').length,
});

// --- 3. Recreate (theme switch) many times: DOM must not accumulate ---
const baseline = document.body.querySelectorAll('*').length;
for (let i = 0; i < 25; i++) {
  const c = new Yagr(host, createConfig(feed, i % 2 ? 'dark' : 'light'));
  const u = feed.subscribe((t, v) => c.setSeries([t], [{id: SERIES_ID, data: [v]}], {incremental: true, splice: true}));
  c.dispose();
  u();
}
report('after 25 recreate cycles', {
  bodyNodesBaseline: baseline,
  bodyNodesNow: document.body.querySelectorAll('*').length,
  uplotNodes: document.querySelectorAll('.uplot').length,
  tooltipNodes: document.querySelectorAll('.yagr-tooltip').length,
});

// --- 4. Listener/timer hygiene of the feed ---
const probe = [];
const off = feed.subscribe(() => probe.push(1));
off();
feed.start();
feed.stop();
feed.start();
feed.stop();
report('feed hygiene', {leftoverListenerCalls: probe.length});

