61	/**
62	 * 24h CPU load chart. Fills its parent (the parent must have a definite size).
63	 *
64	 * The Yagr instance is recreated when the theme changes and disposed on unmount.
65	 * Between those points, each feed tick is applied as an incremental update (append
66	 * the new point, drop the oldest) without rebuilding the 43k-point dataset.
67	 */
68	export function CpuUsageChart({feed}: CpuUsageChartProps) {
69	  const hostRef = useRef<HTMLDivElement>(null);
70	  const theme = useThemeType();
71	
72	  useEffect(() => {
73	    const host = hostRef.current;
74	    if (!host) return;
75	
76	    const chart = new Yagr(host, createConfig(feed, theme));
77	    const unsubscribe = feed.subscribe((t, v) => {
78	      chart.setSeries([t], [{id: SERIES_ID, data: [v]}], {incremental: true, splice: true});
79	    });
80	
81	    return () => {
82	      unsubscribe();
83	      chart.dispose();
84	    };
85	  }, [feed, theme]);
86	
87	  return (
88	    <div className="cpu-chart">
89	      <div
90	        ref={hostRef}
91	        className="cpu-chart__plot"
92	        role="img"
93	        aria-label="График загрузки CPU за последние 24 часа"
94	      />
95	    </div>
96	  );
97	}
98

